_SETS = {}


def members(typeId):
	"""Set of historized member paths for a UDT type (cached)."""
	s = _SETS.get(typeId)
	if s is None:
		s = set([m for m in TYPES.get(typeId, '').split('|') if m])
		_SETS[typeId] = s
	return s


def tags():
	"""Set of standalone historized atomic tag paths (cached)."""
	s = _SETS.get('__tags__')
	if s is None:
		s = set([t for t in TAGS.split('|') if t])
		_SETS['__tags__'] = s
	return s
